#include <stdio.h>

int main(void) {
    unsigned value;
    int width;
    while (scanf("%u %d", &value, &width) == 2) {
        for (int i = width - 1; i >= 0; i--) {
            putchar((value >> i) & 1u ? '1' : '0');
            if (i % 4 == 0 && i != 0) {
                putchar(' ');
            }
        }
        putchar('\n');
    }
    return 0;
}

