#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>

int main(void) {
    uint32_t x;
    while (scanf("%" SCNu32, &x) == 1) {
        int ones = 0;
        for (uint32_t rest = x; rest != 0; rest &= rest - 1) {
            ones++;
        }
        printf("%" PRIu32 ": единиц %d, младший бит ", x, ones);
        if (x == 0) {
            printf("нет");
        } else {
            uint32_t low = x & -x;
            int position = 0;
            while (low > 1) {
                low >>= 1;
                position++;
            }
            printf("%d", position);
        }
        printf(", степень двойки %s\n", x != 0 && (x & (x - 1)) == 0 ? "да" : "нет");
    }
    return 0;
}

