static const char *yes_no(int value) {
    return value ? "да" : "нет";
}

int main(void) {
    unsigned perm;
    while (scanf("%u", &perm) == 1) {
        int can_read = perm & READ == READ;
        int can_write = perm & WRITE == WRITE;
        int can_exec = perm & EXEC == EXEC;
        printf("%u: чтение %s, запись %s, выполнение %s\n", perm, yes_no(can_read),
               yes_no(can_write), yes_no(can_exec));
    }
    return 0;
}

