#include <stdint.h>
#include <stdio.h>

static uint32_t make_ip(unsigned a, unsigned b, unsigned c, unsigned d) {
    return (uint32_t)a << 24 | (uint32_t)b << 16 | (uint32_t)c << 8 | (uint32_t)d;
}

static void print_ip(uint32_t ip) {
    printf("%u.%u.%u.%u", (unsigned)(ip >> 24), (unsigned)(ip >> 16) & 0xFFu,
           (unsigned)(ip >> 8) & 0xFFu, (unsigned)ip & 0xFFu);
}

int main(void) {
    unsigned a, b, c, d, prefix;
    if (scanf("%u.%u.%u.%u/%u", &a, &b, &c, &d, &prefix) != 5 || prefix > 32) {
        return 0;
    }
    uint32_t mask = prefix == 0 ? 0 : 0xFFFFFFFFu << (32 - prefix);
    uint32_t network = make_ip(a, b, c, d) & mask;
    printf("сеть ");
    print_ip(network);
    printf(", маска ");
    print_ip(mask);
    printf("\n");
    while (scanf("%u.%u.%u.%u", &a, &b, &c, &d) == 4) {
        uint32_t addr = make_ip(a, b, c, d);
        print_ip(addr);
        printf(": %s\n", (addr & mask) == network ? "в сети" : "вне сети");
    }
    return 0;
}

